import 'package:flutter/material.dart';
import 'package:provider/provider.dart';
import '../main.dart';
import '../theme/app_theme.dart';
class SetupScreen extends StatefulWidget { const SetupScreen({super.key}); @override State<SetupScreen> createState() => _SetupScreenState(); }
class _SetupScreenState extends State<SetupScreen> { final url = TextEditingController(text: 'http://localhost:3001'); final name = TextEditingController(text: 'PrintBridge Agent'); bool loading = false; String? error; @override Widget build(BuildContext context) => Scaffold(body: Center(child: ConstrainedBox(constraints: const BoxConstraints(maxWidth: 480), child: Card(margin: const EdgeInsets.all(24), child: Padding(padding: const EdgeInsets.all(32), child: Column(mainAxisSize: MainAxisSize.min, crossAxisAlignment: CrossAxisAlignment.start, children: [Container(width: 42, height: 42, alignment: Alignment.center, color: AppTheme.green, child: const Text('PB', style: TextStyle(color: Color(0xFF07120D), fontWeight: FontWeight.w900))), const SizedBox(height: 36), Text('Connect your agent', style: Theme.of(context).textTheme.headlineMedium?.copyWith(fontWeight: FontWeight.w800)), const SizedBox(height: 10), const Text('Register this workstation with your PrintBridge control room.'), const SizedBox(height: 28), TextField(controller: url, decoration: const InputDecoration(labelText: 'Server URL', prefixIcon: Icon(Icons.dns_outlined))), const SizedBox(height: 16), TextField(controller: name, decoration: const InputDecoration(labelText: 'Device name', prefixIcon: Icon(Icons.computer_outlined))), if (error != null) Padding(padding: const EdgeInsets.only(top: 16), child: Text(error!, style: const TextStyle(color: AppTheme.red))), const SizedBox(height: 24), SizedBox(width: double.infinity, child: FilledButton(onPressed: loading ? null : _register, child: Text(loading ? 'Registering...' : 'Register device  ↗')))]))))));
